ALTER TYPE public.app_role ADD VALUE IF NOT EXISTS 'seller';
ALTER TYPE public.app_role ADD VALUE IF NOT EXISTS 'sdr';
ALTER TYPE public.app_role ADD VALUE IF NOT EXISTS 'attendant';
ALTER TYPE public.app_role ADD VALUE IF NOT EXISTS 'traffic_manager';
CREATE OR REPLACE FUNCTION public.crm_has_any_role(uid uuid, roles text[]) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=uid AND role::text=ANY(roles)) $$;
REVOKE ALL ON FUNCTION public.crm_has_any_role(uuid,text[]) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.crm_has_any_role(uuid,text[]) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.can_view_leads(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.crm_has_any_role(_user_id,ARRAY['super_admin','admin','collaborator','seller','sdr','attendant']) $$;
CREATE OR REPLACE FUNCTION public.crm_can_sell(uid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.crm_has_any_role(uid,ARRAY['super_admin','admin','collaborator','seller']) $$;
CREATE OR REPLACE FUNCTION public.crm_can_read_lead(lid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.crm_is_admin() OR (public.can_view_leads(auth.uid()) AND EXISTS(SELECT 1 FROM public.leads WHERE id=lid AND assigned_to=auth.uid())) $$;
REVOKE ALL ON FUNCTION public.crm_can_sell(uuid),public.crm_can_read_lead(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.crm_can_sell(uuid),public.crm_can_read_lead(uuid) TO authenticated,service_role;
ALTER POLICY "Team reads leads" ON public.leads USING(public.crm_is_admin() OR (public.can_view_leads(auth.uid()) AND assigned_to=auth.uid()));
ALTER POLICY "Team updates lead funnel" ON public.leads USING(public.crm_can_read_lead(id)) WITH CHECK(public.crm_can_read_lead(id));
CREATE OR REPLACE FUNCTION public.crm_guard_staff_lead() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
 IF auth.uid() IS NOT NULL AND NOT public.crm_is_admin() THEN
 IF NEW.assigned_to IS DISTINCT FROM OLD.assigned_to THEN RAISE EXCEPTION 'Only admins assign leads'; END IF;
 IF public.crm_has_any_role(auth.uid(),ARRAY['attendant']) AND (NEW.funnel_stage IS DISTINCT FROM OLD.funnel_stage OR NEW.contract_value IS DISTINCT FROM OLD.contract_value OR NEW.closing_notes IS DISTINCT FROM OLD.closing_notes OR NEW.loss_reason IS DISTINCT FROM OLD.loss_reason) THEN RAISE EXCEPTION 'Attendants may only update returns'; END IF;
 END IF; RETURN NEW; END $$;
CREATE TRIGGER crm_guard_staff_lead BEFORE UPDATE ON public.leads FOR EACH ROW EXECUTE FUNCTION public.crm_guard_staff_lead();
ALTER POLICY "Team reads agendamentos" ON public.agendamentos USING(public.crm_is_admin() OR public.crm_can_read_lead(lead_id));
ALTER POLICY "Team creates agendamentos" ON public.agendamentos WITH CHECK(public.crm_is_admin() OR (public.crm_has_any_role(auth.uid(),ARRAY['collaborator','seller','sdr']) AND public.crm_can_read_lead(lead_id) AND public.can_view_leads(responsavel_id)));
ALTER POLICY "Team updates agendamentos" ON public.agendamentos USING(public.crm_is_admin() OR (public.crm_has_any_role(auth.uid(),ARRAY['collaborator','seller','sdr']) AND public.crm_can_read_lead(lead_id))) WITH CHECK(public.crm_is_admin() OR public.crm_can_read_lead(lead_id));
ALTER POLICY sales_read ON public.sales USING(public.crm_is_admin() OR (public.crm_can_sell(auth.uid()) AND seller_id=auth.uid()));
ALTER POLICY sales_insert ON public.sales WITH CHECK(public.crm_can_sell(seller_id) AND (public.crm_is_admin() OR (public.crm_can_sell(auth.uid()) AND seller_id=auth.uid() AND public.crm_can_read_lead(lead_id))));
ALTER POLICY sales_update ON public.sales USING(public.crm_is_admin() OR (public.crm_can_sell(auth.uid()) AND seller_id=auth.uid())) WITH CHECK(public.crm_is_admin() OR (public.crm_can_sell(auth.uid()) AND seller_id=auth.uid() AND public.crm_can_read_lead(lead_id)));
ALTER POLICY payments_read ON public.sale_payments USING(public.crm_is_admin());
ALTER POLICY payments_insert ON public.sale_payments WITH CHECK(public.crm_is_admin() AND EXISTS(SELECT 1 FROM public.sales s WHERE s.id=sale_id AND s.status='valida'));
ALTER POLICY payments_update ON public.sale_payments USING(public.crm_is_admin()) WITH CHECK(public.crm_is_admin());
ALTER POLICY contracts_read ON public.contracts USING(public.crm_is_admin() OR (public.crm_can_sell(auth.uid()) AND seller_id=auth.uid()));
ALTER POLICY installments_read ON public.contract_installments USING(public.crm_is_admin());
ALTER POLICY activities_team_read ON public.crm_activities USING(public.crm_is_admin() OR (public.crm_can_read_lead(lead_id) AND (type NOT IN ('sale_created','contract_created','contract_cancelled','installment_paid') OR (public.crm_can_sell(auth.uid()) AND owner_id=auth.uid()))));
CREATE OR REPLACE FUNCTION public.crm_register_sale(payload jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE sale_id uuid := (payload->>'id')::uuid; BEGIN
 IF auth.uid() IS NULL OR NOT public.crm_can_sell(auth.uid()) THEN RAISE EXCEPTION 'Sales access denied'; END IF;
 IF EXISTS(SELECT 1 FROM public.sales WHERE id=sale_id) THEN RETURN sale_id; END IF;
 INSERT INTO public.sales(id,lead_id,seller_id,service,closed_on,initial_value,monthly_value,contract_type,starts_on,contract_status,notes) VALUES(sale_id,(payload->>'lead_id')::uuid,(payload->>'seller_id')::uuid,payload->>'service',(payload->>'closed_on')::date,(payload->>'initial_value')::numeric,(payload->>'monthly_value')::numeric,payload->>'contract_type',(payload->>'starts_on')::date,payload->>'contract_status',payload->>'notes');
 IF public.crm_is_admin() THEN INSERT INTO public.sale_payments(sale_id,amount,status,received_on,method) VALUES(sale_id,(payload->>'payment_amount')::numeric,payload->>'payment_status',NULLIF(payload->>'received_on','')::date,payload->>'payment_method'); END IF;
 RETURN sale_id; END $$;
CREATE TABLE public.traffic_clients (lead_id uuid PRIMARY KEY REFERENCES public.leads(id), manager_id uuid, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.traffic_clients TO authenticated; GRANT ALL ON public.traffic_clients TO service_role;
ALTER TABLE public.traffic_clients ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.traffic_access(lid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.crm_is_admin() OR (public.crm_has_any_role(auth.uid(),ARRAY['traffic_manager']) AND EXISTS(SELECT 1 FROM public.traffic_clients WHERE lead_id=lid AND manager_id=auth.uid())) $$;
REVOKE ALL ON FUNCTION public.traffic_access(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.traffic_access(uuid) TO authenticated,service_role;
CREATE POLICY traffic_clients_read ON public.traffic_clients FOR SELECT TO authenticated USING(public.traffic_access(lead_id));
CREATE POLICY traffic_clients_insert ON public.traffic_clients FOR INSERT TO authenticated WITH CHECK(public.crm_is_admin());
CREATE POLICY traffic_clients_update ON public.traffic_clients FOR UPDATE TO authenticated USING(public.crm_is_admin()) WITH CHECK(public.crm_is_admin());
CREATE TABLE public.traffic_campaigns (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lead_id uuid NOT NULL REFERENCES public.traffic_clients(lead_id), name text NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 120), platform text NOT NULL CHECK(platform IN ('Meta Ads','Google Ads','Outra')), objective text NOT NULL DEFAULT '', budget numeric NOT NULL DEFAULT 0 CHECK(budget>=0), starts_on date NOT NULL, status text NOT NULL DEFAULT 'Planejamento' CHECK(status IN ('Planejamento','Ativa','Pausada','Encerrada')), notes text NOT NULL DEFAULT '', updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.traffic_campaigns TO authenticated; GRANT ALL ON public.traffic_campaigns TO service_role;
ALTER TABLE public.traffic_campaigns ENABLE ROW LEVEL SECURITY;
CREATE POLICY traffic_campaigns_read ON public.traffic_campaigns FOR SELECT TO authenticated USING(public.traffic_access(lead_id));
CREATE POLICY traffic_campaigns_insert ON public.traffic_campaigns FOR INSERT TO authenticated WITH CHECK(public.traffic_access(lead_id));
CREATE POLICY traffic_campaigns_update ON public.traffic_campaigns FOR UPDATE TO authenticated USING(public.traffic_access(lead_id)) WITH CHECK(public.traffic_access(lead_id));
CREATE TABLE public.traffic_results (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), campaign_id uuid NOT NULL REFERENCES public.traffic_campaigns(id), starts_on date NOT NULL, ends_on date NOT NULL CHECK(ends_on>=starts_on), spend numeric NOT NULL CHECK(spend>=0), impressions bigint CHECK(impressions>=0), reach bigint CHECK(reach>=0), clicks bigint CHECK(clicks>=0), leads bigint CHECK(leads>=0), conversions bigint CHECK(conversions>=0), notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), EXCLUDE USING gist (campaign_id WITH =, daterange(starts_on,ends_on,'[]') WITH &&));
GRANT SELECT,INSERT ON public.traffic_results TO authenticated; GRANT ALL ON public.traffic_results TO service_role;
ALTER TABLE public.traffic_results ENABLE ROW LEVEL SECURITY;
CREATE POLICY traffic_results_read ON public.traffic_results FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.traffic_campaigns c WHERE c.id=campaign_id AND public.traffic_access(c.lead_id)));
CREATE POLICY traffic_results_insert ON public.traffic_results FOR INSERT TO authenticated WITH CHECK(EXISTS(SELECT 1 FROM public.traffic_campaigns c WHERE c.id=campaign_id AND public.traffic_access(c.lead_id)));
CREATE OR REPLACE FUNCTION public.traffic_log_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE lid uuid; msg text; BEGIN
 IF TG_TABLE_NAME='traffic_campaigns' THEN lid=NEW.lead_id; msg=CASE WHEN TG_OP='INSERT' THEN 'Campanha criada: ' ELSE 'Campanha atualizada: ' END || NEW.name; ELSE SELECT lead_id INTO lid FROM public.traffic_campaigns WHERE id=NEW.campaign_id; msg='Resultados registrados'; END IF;
 UPDATE public.traffic_clients SET updated_at=now() WHERE lead_id=lid;
 INSERT INTO public.crm_activities(type,entity_id,lead_id,client_name,company,actor_id,actor_name,owner_id,description) SELECT 'traffic_operation',NEW.id,lid,l.name,l.company,auth.uid(),(SELECT email FROM auth.users WHERE id=auth.uid()),tc.manager_id,msg FROM public.leads l JOIN public.traffic_clients tc ON tc.lead_id=l.id WHERE l.id=lid;
 RETURN NEW; END $$;
CREATE TRIGGER traffic_campaign_log AFTER INSERT OR UPDATE ON public.traffic_campaigns FOR EACH ROW EXECUTE FUNCTION public.traffic_log_change();
CREATE TRIGGER traffic_result_log AFTER INSERT ON public.traffic_results FOR EACH ROW EXECUTE FUNCTION public.traffic_log_change();
CREATE POLICY traffic_activity_read ON public.crm_activities FOR SELECT TO authenticated USING(type='traffic_operation' AND public.traffic_access(lead_id));
CREATE OR REPLACE FUNCTION public.traffic_add_note(lid uuid,description text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
 IF NOT public.traffic_access(lid) OR length(trim(description)) NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'Unauthorized or invalid activity'; END IF;
 INSERT INTO public.crm_activities(type,entity_id,lead_id,client_name,company,actor_id,actor_name,owner_id,description) SELECT 'traffic_operation',lid,lid,l.name,l.company,auth.uid(),(SELECT email FROM auth.users WHERE id=auth.uid()),tc.manager_id,description FROM public.leads l JOIN public.traffic_clients tc ON tc.lead_id=l.id WHERE l.id=lid;
 UPDATE public.traffic_clients SET updated_at=now() WHERE lead_id=lid; END $$;
REVOKE ALL ON FUNCTION public.traffic_add_note(uuid,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.traffic_add_note(uuid,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.traffic_client_info() RETURNS TABLE(id uuid,name text,company text,service text,manager_id uuid,manager_email text,updated_at timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT l.id,l.name,l.company,COALESCE((SELECT string_agg(DISTINCT s.service,', ') FROM public.sales s WHERE s.lead_id=l.id AND s.status='valida'),''),tc.manager_id,(SELECT email::text FROM auth.users WHERE auth.users.id=tc.manager_id),tc.updated_at FROM public.leads l LEFT JOIN public.traffic_clients tc ON tc.lead_id=l.id WHERE public.crm_is_admin() OR (tc.lead_id IS NOT NULL AND public.traffic_access(l.id)) $$;
REVOKE ALL ON FUNCTION public.traffic_client_info() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.traffic_client_info() TO authenticated;